"""Build the single-stream report using the requested seven-experiment outline."""
from pathlib import Path
import pandas as pd
from report_experiments import single_experiments,single_supplement,version_report_images
ROOT=Path(__file__).resolve().parent
INTRO = '# UPA单极化单流正式实验报告\n\n2026年10月23日。已完成400个冻结位置的UPA单极化单流扫描，共98,800条记录，包含19个曲线标签、16个不同物理配置。所有有限反馈消息、数值指标和汇总均值均经独立Python程序核验。CPU与UE分别报告，双流结果另见专门报告。\n\n2026年10月24日补齐全部22幅实验图、对应逐点数值和结论，实验数据不变。最新单流与双流统一在feat/upa-single-dual-complete-20261024维护，后续修改继续使用该分支。\n\n## 1 方法与实验口径\n\n| 项目 | 设置 |\n|---|---|\n| AP与UE | 默认8个AP，每AP32×32单极化UPA，UE有4个接收阵元 |\n| 阵列扫描 | 每AP8×8、16×16、32×32 |\n| AP扫描 | 5至10个AP |\n| 信道 | 正式单流扫描为LOS加散射多径的混合信道 |\n| 观测SNR扫描 | 20至40 dB，间隔5 dB；默认30 dB |\n| 莱斯因子扫描 | 0至20 dB，间隔5 dB；默认10 dB |\n| 位置 | 同一冻结样本库的1至400，全部保留 |\n| 主参考 | 无信道估计噪声的真实信道直接SVD，使用第一右奇异向量 |\n| 功率与速率 | 总功率1，可实施方案每AP功率1/B；Mbps等于400乘频谱效率 |\n\n真实信道包含实际LOS与散射传播，无额外的信道估计噪声；观测信道是在其上添加估计噪声。普通方法只用观测CSI设计，真实信道仅供评价。数据噪声通过固定数据链路rho体现，不因“完美CSI”而消失。SVD是总功率约束下的最优单流上界，放松每AP等功率限制。\n\n400 MHz仅直接换算，不引入OFDM或带宽相关噪声重标定。同算法观测与完美CSI配对仅为此前小样本补充，未扩入正式主扫描。\n\n19个标签分别服务SNR、阵元数、AP数和K曲线，默认配置重复四次。程序缓存重复默认点，因此实际计算16个物理配置共6,400个位置与配置案例；按曲线标签展开为7,600个案例，不将重复标签当成新样本。\n\n### 方法与实现过程\n\nType-I从联合观测信道的主右奇异向量按AP分块匹配二维DFT波束。Type-II在同一正交分组内选两条，组合幅度3 bit、内部相位2 bit。普通五种UE方法统一采用主模式投影，将首AP相位固定0后，对其余相对相位量化4 bit。\n\n位置反馈由连续空间频率在UE定位，然后仅量化一次坐标，固定13/14/9 bit。UE按CPU同样的解码规则恢复波束，再用观测CSI计算共相位。CPU则只凭空间消息和公共几何重构模型并计算相位，不接收参考AP完整观测信道。上述核心口径此前已在第5、第6目录建立，本轮是恢复新增单流入口的一致性并补齐完整消息重放。\n\n每个方法实际打包整数比特串，再由CPU独立恢复最终发送向量。统计有效载荷，不含预先共享的方法配置、传输头和FEC；JSON仅用于审计，不按JSON文本长度计费。\n\n### Docomo实现与前期调试\n\n依据Li、Hou、Chen的Near-Field Line-of-Sight MIMO Precoding with Distributed Antennas，IEEE PIMRC 2024，第IV节式25至27和第V节。保留每AP本地DFT波束、QPSK共相位和跨AP模式的分块结构。当前不规则AP使用公开顺序的一维逻辑DFT，固定单极化单流、项目码本和三轮坐标更新；不称为完整论文复现。论文的Type-I是NCJT，当前项目Type-I含共相位，两者名称相近但定义不同。\n\nDocomo专项48项检查通过，覆盖三种UPA、B为4/8/10的9个随机案例及6个物理LOS或混合信道案例。交替更新观测目标不下降，解码重建误差0。B=4时固定本地波束，枚举256种相位与模式组合；三个随机案例与枚举最优值一致，但不证明联合波束全局最优。701项协议检查和此前42项UPA及位置反馈检查仍通过。\n\n默认Docomo反馈129 bit，由本地索引、QPSK beta和AP模式索引实际编码得到，不能套用论文特定场景的26 bit。\n\n正文按CPU、UE分开，各自只列定位误差与SNR、天线数、AP数，吞吐量与SNR、天线数、莱斯因子，以及比特数与AP数七项实验。默认配置对照、频谱效率、坐标量化与越界等已完成内容放在末尾补充。'
PRIOR_SUPPLEMENT = "### CPU默认配置补充对照\n\n下表为默认配置的400位置均值，列出CPU三种几何方法和Docomo(UE)共享参考。\n\n| 方法 | 平均吞吐量 Mbps | 定位误差 m | 反馈 bit |\n|---|---:|---:|---:|\n| 空间频率 | 3177.396 | 0.008532 | 84 |\n| DFT索引 | 2909.626 | 0.235091 | 42 |\n| 位置反馈 | 3184.002 | 0.009490 | 36 |\n| Docomo(UE) | 3347.721 | 不适用 | 129 |\n\n位置反馈以36 bit获得3184.002 Mbps，空间频率反馈以84 bit获得3177.396 Mbps，当前默认点两者速率相近。位置误差略大并不必然导致更低速率，因为坐标量化按相对相位敏感度分配，定位欧氏误差不是唯一性能因素。DFT索引定位误差较大，对CPU几何共相位的影响更明显。\n\nCPU图中的全反馈Type-I(UE)、全反馈Type-II(UE)和Docomo(UE)均为UE计算的共享参考。默认均值分别为3298.510、3324.283和3347.721 Mbps；理想单流SVD为3543.540 Mbps。Docomo(UE)反馈129 bit，结果直接复用UE数据，不新增CPU算法或样本。定位误差图只列有位置输出的三种几何方法。\n\n\n### UE默认配置补充对照\n\n下表同样为默认配置的400位置均值；几何位置仍来自带噪观测，不是完美CSI输入。\n\n| 方法 | 平均吞吐量 Mbps | 定位误差 m | 反馈 bit |\n|---|---:|---:|---:|\n| 全反馈Type-I(UE) | 3298.510 | 不适用 | 140 |\n| 全反馈Type-II(UE) | 3324.283 | 不适用 | 292 |\n| Docomo | 3347.721 | 不适用 | 129 |\n| 空间频率 | 3307.265 | 0.008532 | 112 |\n| DFT索引 | 3300.250 | 0.235091 | 70 |\n| 位置反馈 | 3307.261 | 0.009490 | 64 |\n\n位置反馈与空间频率默认平均速率分别为3307.261和3307.265 Mbps，而反馈64与112 bit，减少约42.9%。这支持本配置下位置反馈的压缩价值，不宣称所有配置严格等效。UE由观测信道计算共相位，能补偿部分定位误差对跨AP相位的影响；因此DFT方案在UE侧比CPU侧更接近其他几何方法。\n\nDocomo在此配置达到3347.721 Mbps、129 bit。由于场景、码本和项目基线定义与论文不同，不将本排序称为论文图表复现。\n\n\n### 定位越界与统计解释\n\n| K dB | 坐标量化前误差 m | 坐标解码后误差 m | 越界比例 |\n|---:|---:|---:|---:|\n| 0 | 2.139687 | 1.288964 | 15.0% |\n| 5 | 0.014612 | 0.015313 | 0.0% |\n| 10 | 0.008249 | 0.009490 | 0.0% |\n| 15 | 0.004710 | 0.006290 | 0.0% |\n| 20 | 0.002762 | 0.004884 | 0.0% |\n\nK=0 dB不是纯NLOS，而是LOS和NLOS功率相当。该点60个位置越界，占400个位置的15%；原始误差2.139687 m，解码后1.288964 m。改善主要包含区域截断先验，不能称为量化提升定位精度。CPU与UE共享同一坐标消息，120条越界记录对应同一批60个位置在两分支中的重复记录。\n\n### 原运行验证证据与复现\n\n独立审计核验83,600条有限反馈记录，最大预编码检查量误差约5.22×10⁻¹¹，CPU相位系数误差约2.35×10⁻¹⁰。所有247个汇总组均包含400个不同位置，无缺失、无重复样本，全部均值重新计算。\n\n原始CSV为120,691,123字节，GitHub提供无损gzip约18.5 MB；压缩前与解压后SHA256一致。本地保留CSV，远端可直接用pandas读取gzip，MATLAB绘图入口也支持自动解压。冻结依赖、历史数据和已有分支均未改动。\n\n```matlab\nrun_single_stream_task2('Mode','full','IncludeCSIPairs',false,'OutputDir','results/new_full400');\n```\n\n```text\npython audit_single_stream_protocol.py results/single_stream_V3_full400\n```\n\n本轮已经完成正式单流扫描；不将绝对Mbps解读为完整物理系统吞吐量。结论限定于当前冻结信道、总功率、码本和400 MHz换算口径。双流已按同一400位置和参数逐条配对核对，结果另见双流完整报告，不混入本报告的单流统计。\n\n"

def build():
    if (ROOT/'results/upa_snr_revision400_20261025/assembly_audit.json').exists():
        from build_snr_revision_reports import build as current_build
        current_build((1,))
        return
    s=pd.read_csv(ROOT/'results/single_stream_V3_full400/single_stream_summary.csv')
    parts=[INTRO]+single_experiments('CPU',s)+single_experiments('UE',s)+['## 4 额外补充',PRIOR_SUPPLEMENT]+single_supplement('CPU',s)+single_supplement('UE',s)
    content='\n\n'.join(parts)+'\n'
    content=version_report_images(content)
    dest=ROOT/'docs/UPA单流400位置正式实验报告.md';dest.write_text(content,encoding='utf-8');print(dest)

if __name__=='__main__':build()
